class Node:
    def __init__(self, key): self.key, self.left, self.right = key, None, None
def insert(node, key):
    if node is None: return Node(key)
    if key < node.key: node.left = insert(node.left, key)
    elif key > node.key: node.right = insert(node.right, key)
    return node
def walk(node):                      # in-order: left, self, right
    if node: yield from walk(node.left); yield node.key; yield from walk(node.right)
root = None
for k in [50, 30, 70, 20, 40]: root = insert(root, k)
print(list(walk(root)))              # [20, 30, 40, 50, 70]

from collections import deque
graph = {"A": ["B", "C"], "B": ["D"], "C": ["D", "E"], "D": ["F"], "E": ["F"], "F": []}
prev, queue = {"A": None}, deque(["A"])          # breadth-first search from A
while queue:
    node = queue.popleft()
    for nxt in graph[node]:
        if nxt not in prev: prev[nxt] = node; queue.append(nxt)
path, node = [], "F"
while node: path.append(node); node = prev[node]
print(path[::-1])                                # ['A', 'B', 'D', 'F']

