-- DuckDB: write a Parquet file, then query it in place
COPY (SELECT i AS id, 'region_' || (i % 20) AS region, (i % 1000) / 10.0 AS price
      FROM range(1000000) t(i)) TO 'big.parquet' (FORMAT parquet);
SELECT region, count(*) AS n, round(avg(price), 2) AS avg_price
FROM 'big.parquet' GROUP BY region ORDER BY region LIMIT 3;

