import math
docs = {"cat": [0.9, 0.1, 0.0], "kitten": [0.85, 0.15, 0.05], "car": [0.1, 0.9, 0.2], "truck": [0.05, 0.95, 0.15]}
def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    return dot / (math.sqrt(sum(x * x for x in a)) * math.sqrt(sum(y * y for y in b)))
query = [0.88, 0.12, 0.02]                       # the embedding of a query such as 'small pet'
for name in sorted(docs, key=lambda k: cosine(query, docs[k]), reverse=True):
    print(f"{name:7s} {cosine(query, docs[name]):.3f}")   # cat 0.999, kitten 0.999, car 0.243, truck 0.188

