-- SQL:1999 recursive query: everything reachable from A in a graph stored as rows
CREATE TABLE edges (src TEXT, dst TEXT);
INSERT INTO edges VALUES ('A','B'), ('A','C'), ('B','D'), ('C','D'), ('D','F');
WITH RECURSIVE reach(node, depth) AS (
  SELECT 'A', 0
  UNION
  SELECT e.dst, r.depth + 1 FROM reach AS r JOIN edges AS e ON e.src = r.node
)
SELECT node, MIN(depth) FROM reach GROUP BY node ORDER BY MIN(depth), node;
-- A 0 | B 1 | C 1 | D 2 | F 3
